from lib import *
L = lambda *a, **k: lesson(13, "A0", *a, **k)
A = "adjective"
L(1, "Вони", "Говорити про кількох людей: вони, ми, ви.",
 "They — «вони». З they, we і you завжди стоїть are: They are friends. We are from Ukraine. Скорочено: they're, we're, you're. Усі форми разом: I am, he / she / it is, we / you / they are.",
 [W("they", "/ðeɪ/", "pronoun", "вони", "They're my friends.", "Вони мої друзі."),
  W("people", "/ˈpiːpl/", "noun", "люди", "Ten people.", "Десять людей."),
  W("together", "/təˈɡeðə/", "adverb", "разом", "We work together.", "Ми працюємо разом."),
  W("both", "/bəʊθ/", "pronoun", "обидва, обидві", "We're both teachers.", "Ми обоє вчителі."),
  W("colleague", "/ˈkɒliːɡ/", "noun", "колега", "She's my colleague.", "Вона моя колега.")],
 [li("Whose keys are these?", "Повторимо. Ключі ваші. Що відповісти?", ["They're mine.", "It's my.", "They're me."], "They're mine."),
  mt([("they", "вони"), ("we", "ми"), ("people", "люди"), ("both", "обидва")], "People — множина від person, без -s."),
  mt([("together", "разом"), ("colleague", "колега"), ("friend", "друг"), ("neighbour", "сусід")], "Люди навколо нас."),
  fb("They ___ from Poland.", ["are", "is", "am"], "З they — are."),
  fb("My brother and I ___ students.", ["are", "is", "am"], "Мій брат і я — це «ми», тому are."),
  fb("Anna ___ my colleague.", ["is", "are", "am"], "Одна людина — is."),
  liu("We're both from Ukraine.", "Прослухайте. Що каже людина?", ["Ми обоє з України", "Вони обоє з України", "Ми разом в Україні"], "We're both — ми обоє."),
  bs("Вони мої друзі.", ["They", "are", "my", "friends"], ["is", "their"], "They are my friends."),
  tr("Ми працюємо разом.", ["We work together"], "We work together."),
  li("Who are these people?", "Це ваші колеги. Що відповісти?", ["They're my colleagues.", "It's my colleagues.", "He's my colleagues."], "They're my colleagues.")])
L(2, "Ні, це не так", "Заперечити: я не…, він не…, вони не…",
 "Заперечення — це not після am, is, are. Скорочено: I'm not, he isn't, she isn't, we aren't, they aren't. I'm not married. They aren't ready.",
 [W("aren't", "/ɑːnt/", "verb", "не є (з we, you, they)", "They aren't here.", "Їх тут немає."),
  W("married", "/ˈmærid/", A, "одружений, заміжня", "I'm not married.", "Я не одружений."),
  W("single", "/ˈsɪŋɡl/", A, "неодружений, незаміжня", "He's single.", "Він неодружений."),
  W("ready", "/ˈredi/", A, "готовий", "I'm ready.", "Я готовий."),
  W("happy", "/ˈhæpi/", A, "щасливий, радий", "She's happy.", "Вона щаслива."),
  W("sad", "/sæd/", A, "сумний", "He isn't sad.", "Він не сумний.")],
 [fb("They ___ my neighbours.", ["are", "is", "am"], "They are.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("married", "одружений"), ("single", "неодружений"), ("ready", "готовий"), ("happy", "щасливий"), ("sad", "сумний")], "Happy і sad — протилежні слова."),
  fb("He ___ married. He's single.", ["isn't", "aren't", "am not"], "З he — isn't."),
  fb("We ___ ready. Five minutes, please!", ["aren't", "isn't", "am not"], "З we — aren't."),
  fb("I'm ___ a doctor. I'm a nurse.", ["not", "no", "isn't"], "З I — I'm not."),
  liu("They aren't at home.", "Прослухайте. Що каже людина?", ["Їх немає вдома", "Вони вдома", "Вони не тут працюють"], "They aren't — їх немає, вони не…"),
  mc("Як сказати «Вона не заміжня»?", ["She isn't married.", "She aren't married.", "She not married."], "She isn't married."),
  bs("Я не готовий.", ["I'm", "not", "ready"], ["isn't", "no"], "I'm not ready."),
  tr("Вони не сумні.", ["They aren't sad", "They are not sad", "They're not sad"], "They aren't sad."),
  li("Are you married?", "Ви неодружені. Що відповісти?", ["No, I'm not. I'm single.", "No, I isn't. I'm single.", "No, I aren't."], "No, I'm not. I'm single.")])
L(3, "Усе гаразд?", "Спитати про стан людини й коротко відповісти.",
 "Питання будують перестановкою: You are OK → Are you OK? Коротка відповідь повторює дієслово: Yes, I am. No, I'm not. Is he ill? — Yes, he is. No, he isn't.",
 [W("ill", "/ɪl/", A, "хворий", "He's ill.", "Він хворий."),
  W("well", "/wel/", A, "здоровий; добре", "I'm not very well.", "Я почуваюся не дуже добре."),
  W("angry", "/ˈæŋɡri/", A, "сердитий", "Are you angry?", "Ви сердитеся?"),
  W("worried", "/ˈwʌrid/", A, "стурбований", "She's worried.", "Вона хвилюється."),
  W("all right", "/ˌɔːl ˈraɪt/", A, "у порядку", "Are you all right?", "З вами все гаразд?")],
 [fb("They ___ at home. They're on holiday.", ["aren't", "isn't", "am not"], "They aren't.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("ill", "хворий"), ("well", "здоровий"), ("angry", "сердитий"), ("worried", "стурбований"), ("all right", "у порядку")], "Слова про стан людини."),
  mc("Як спитати «Ви готові?»", ["Are you ready?", "You are ready?", "Is you ready?"], "Питання починається з Are."),
  mc("Як спитати «Він хворий?»", ["Is he ill?", "He is ill?", "Are he ill?"], "З he — Is he…?"),
  fb("Are you tired? — Yes, I ___.", ["am", "is", "are"], "Yes, I am."),
  fb("Is she angry? — No, she ___.", ["isn't", "aren't", "not"], "No, she isn't."),
  liu("Are you all right?", "Прослухайте. Що вас питають?", ["З вами все гаразд?", "Ви праві?", "Ви вже тут?"], "All right — у порядку."),
  bs("Вони готові?", ["Are", "they", "ready"], ["is", "their"], "Are they ready?"),
  tr("Ви хвилюєтеся?", ["Are you worried"], "Are you worried?"),
  li("Are you OK?", "Ви погано почуваєтеся. Що відповісти?", ["No, I'm not very well.", "No, I isn't well.", "Yes, I'm ill fine."], "No, I'm not very well.")])
L(4, "Де вони зараз?", "Сказати, де хтось перебуває.",
 "Where are they? — «Де вони?». Місця з at: at home, at work, at school. Про відпустку — on holiday. Upstairs — нагорі, downstairs — унизу, outside — надворі: ці слова вживають без at чи in.",
 [W("at work", "/ət ˈwɜːk/", "phrase", "на роботі", "He's at work.", "Він на роботі."),
  W("outside", "/ˌaʊtˈsaɪd/", "adverb", "надворі", "The children are outside.", "Діти надворі."),
  W("inside", "/ˌɪnˈsaɪd/", "adverb", "усередині", "It's cold. Let's go inside.", "Холодно. Ходімо всередину."),
  W("upstairs", "/ˌʌpˈsteəz/", "adverb", "нагорі", "The bedroom is upstairs.", "Спальня нагорі."),
  W("downstairs", "/ˌdaʊnˈsteəz/", "adverb", "унизу", "The kitchen is downstairs.", "Кухня внизу."),
  W("away", "/əˈweɪ/", "adverb", "у від'їзді", "She's away this week.", "Цього тижня її немає."),]
 ,
 [li("Is he ill?", "Повторимо. Він здоровий. Що відповісти?", ["No, he isn't. He's fine.", "No, he aren't. He's fine.", "Yes, he isn't."], "No, he isn't."),
  mt([("outside", "надворі"), ("inside", "усередині"), ("upstairs", "нагорі"), ("downstairs", "унизу")], "Чотири слова про місце без at чи in."),
  mt([("at work", "на роботі"), ("at home", "удома"), ("at school", "у школі"), ("away", "у від'їзді")], "Сталі вирази з at."),
  liu("Where are the children?", "Прослухайте. Що питає людина?", ["Де діти", "Хто ці діти", "Скільки дітей"], "Where are…? — про кількох."),
  fb("My wife is ___ work.", ["at", "in", "on"], "At work — на роботі."),
  fb("They're ___ holiday in Poland.", ["on", "at", "in"], "On holiday — у відпустці."),
  liu("The bathroom is upstairs.", "Прослухайте. Де ванна кімната?", ["Нагорі", "Унизу", "Надворі"], "Upstairs — нагорі."),
  bs("Діти надворі.", ["The", "children", "are", "outside"], ["is", "at"], "The children are outside."),
  tr("Він на роботі.", ["He's at work", "He is at work"], "He's at work."),
  li("Where is Anna?", "Анни цього тижня немає в місті. Що відповісти?", ["She's away this week.", "She's outside this week at.", "He's away."], "She's away this week.")])
L(5, "Який він? Яка вона?", "Описати людину: зріст і характер.",
 "What is he like? — «Який він?» про вдачу. Відповідь: He's kind and funny. Про зріст: tall — високий, short — низький. Very і not very допомагають уточнити: She's very clever. He isn't very tall.",
 [W("tall", "/tɔːl/", A, "високий (про людину)", "He's very tall.", "Він дуже високий."),
  W("kind", "/kaɪnd/", A, "добрий", "She's very kind.", "Вона дуже добра."),
  W("funny", "/ˈfʌni/", A, "смішний, дотепний", "My brother is funny.", "Мій брат дотепний."),
  W("clever", "/ˈklevə/", A, "розумний", "She's clever.", "Вона розумна."),
  W("friendly", "/ˈfrendli/", A, "привітний", "They're friendly.", "Вони привітні."),
  W("What is he like?", "/ˌwɒt ɪz hi ˈlaɪk/", "phrase", "Який він?", "What is your boss like?", "Який у вас начальник?")],
 [fb("He's ___ holiday this week.", ["on", "at", "in"], "On holiday.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("tall", "високий"), ("kind", "добрий"), ("funny", "дотепний"), ("clever", "розумний"), ("friendly", "привітний")], "Слова, якими описують людей."),
  liu("What is she like?", "Прослухайте. Про що питають?", ["Яка вона за вдачею", "Що їй подобається", "Де вона"], "What is she like? — про вдачу, а не про смаки."),
  liu("He's tall and very friendly.", "Прослухайте. Який він?", ["Високий і дуже привітний", "Низький і привітний", "Високий і дуже дотепний"], "Tall — високий, friendly — привітний."),
  fb("My sister is very ___. She's a doctor.", ["clever", "downstairs", "both"], "Clever — розумна."),
  mc("Як сказати «Він не дуже високий»?", ["He isn't very tall.", "He not very tall.", "He isn't tall very."], "He isn't very tall."),
  mc("Як спитати про вдачу нового колеги?", ["What is he like?", "What does he like?", "How is he?"], "What is he like? — який він. What does he like? — що йому подобається."),
  bs("Мої сусіди дуже добрі.", ["My", "neighbours", "are", "very", "kind"], ["is", "tall"], "My neighbours are very kind."),
  tr("Вона розумна й дотепна.", ["She's clever and funny", "She is clever and funny"], "She's clever and funny."),
  li("What is your teacher like?", "Ваша вчителька добра й привітна. Що відповісти?", ["She's kind and friendly.", "She likes kind and friendly.", "She's a teacher."], "She's kind and friendly.")])
L(6, "Повторення: розповідь про людей", "Розповісти про інших людей: хто вони, де вони, які вони.",
 "Нових слів немає. Повторюємо всі форми: I am, he is, they are; заперечення isn't і aren't; питання Are you…? Is he…?; де люди й які вони.",
 [],
 [fb("My parents ___ at home. They're on holiday.", ["aren't", "isn't", "am not"], "Parents — «вони», тому aren't."),
  bs("Вони обоє лікарі.", ["They", "are", "both", "doctors"], ["is", "together"], "They are both doctors."),
  li("Is your brother married?", "Ваш брат неодружений. Що відповісти?", ["No, he isn't. He's single.", "No, he aren't. He's single.", "No, I'm not."], "No, he isn't. He's single."),
  tr("З вами все гаразд?", ["Are you all right", "Are you OK", "Are you alright"], "Are you all right?"),
  liu("My colleagues are very friendly. We work together in the office.", "Прослухайте. Що ви дізналися?", ["Колеги привітні, працюють разом в офісі", "Колеги привітні, працюють удома", "Сусіди привітні"], "Colleagues — колеги, together — разом."),
  fb("Where ___ the children? — They're upstairs.", ["are", "is", "am"], "Children — множина: are."),
  mc("Як спитати «Який він?» про вдачу?", ["What is he like?", "What he is?", "How he like?"], "What is he like?"),
  tr("Я не сердитий.", ["I'm not angry", "I am not angry"], "I'm not angry."),
  liu("She isn't ill. She's just tired.", "Прослухайте. Що з нею?", ["Вона не хвора, просто втомлена", "Вона хвора й утомлена", "Вона не втомлена"], "Isn't ill — не хвора. Just tired — просто втомлена."),
  li("Are they ready?", "Вони ще не готові. Що відповісти?", ["No, they aren't.", "No, they isn't.", "No, it aren't."], "No, they aren't.")],
 review=True)
